mapper.update:
update sale_order set sale_price = sale_price - #{parm.salePrice},sale_count = sale_count - #{parm.saleCount}
where order_id =#{parm.orderId}
  and sale_count >= #{parm.saleCount}

mapper.select:
SELECT g.goods_id, g.goods_name, DATE_FORMAT(so.create_time, '%Y-%m') AS sale_month, SUM(so.sale_price) AS sale_price, SUM(so.sale_count) AS sale_count FROM goods g JOIN sale_order so ON g.goods_id = so.goods_id
AND DATE_FORMAT(so.create_time, '%Y-%m') >= #{parm.startTime}
AND DATE_FORMAT(so.create_time, '%Y-%m') <= #{parm.endTime}
GROUP BY g.goods_id, g.goods_name, sale_month ORDER BY g.goods_id, sale_month DESC

        SELECT u.user_id, u.nick_name, DATE_FORMAT(s.create_time, '%Y-%m') AS sale_month, SUM(s.sale_price) AS sale_price
        FROM sys_user u
        inner JOIN sale_order s ON u.user_id = s.sale_user
        
            
                and u.user_id =#{parm.userId}
            
            
                AND DATE_FORMAT(s.create_time, '%Y-%m')  >=  #{parm.startTime}
            
            
                AND DATE_FORMAT(s.create_time, '%Y-%m')  <=  #{parm.endTime}
            
        

        GROUP BY u.user_id, u.nick_name, DATE_FORMAT(s.create_time, '%Y-%m')
        ORDER BY  sale_month
        DESC
